MODES = {
    'first': '标准模式',
    'batch': 'PTC 模式',
    'bench': '极简模式',
    'harness': '创造模式',
}


def pick_mode(use):
    if use not in MODES:
        raise ValueError('unknown use: ' + str(use))
    return MODES[use]

