for _bad in ('STANDARD', 'first ', '标准', None, 1, 'BATCH'):
    try:
        pick_mode(_bad)
        assert False, '非法的 use 应该抛 ValueError: %r' % (_bad,)
    except ValueError:
        pass

_want = {'first': '标准模式', 'batch': 'PTC 模式', 'bench': '极简模式', 'harness': '创造模式'}
for _k, _v in _want.items():
    assert pick_mode(_k) == _v, (_k, pick_mode(_k), _v)
_got = [pick_mode(_k) for _k in ('first', 'batch', 'bench', 'harness')]
assert len(set(_got)) == 4, _got

